sys_alias_templates.default_data_template:
{
  "connection": {
    "table": "http_connection",
    "name": "Full Connection",
    "use_mid": true,
    "connection_url": "https://api.example.com",
    "host": "api.example.com",
    "customField": "kept",
    "nested": {
      "connection_url": "converted",
      "use_mid": false
    }
  },
  "credential": {
    "table": "basic_auth_credentials",
    "name": "Full Credential",
    "userName": "admin"
  },
  "additional": {
    "list": [
      1,
      null,
      "two",
      true
    ],
    "emptyObject": {},
    "emptyArray": []
  }
}

sys_alias_templates.dynamic_data_schema:
{
  "connection_fields": [
    {
      "name": "connectionUrl",
      "label": "Base URL",
      "type": "text",
      "mandatory": true,
      "hint": "https://…",
      "defaultValue": "https://api.example.com"
    },
    {
      "name": "port",
      "type": "number",
      "defaultValue": 443
    },
    {
      "name": "useMid",
      "type": "checkbox",
      "defaultValue": false
    },
    {
      "name": "auth",
      "label": "Auth",
      "type": "radio",
      "groups": [
        {
          "name": "basic",
          "label": "Basic",
          "default_group": true,
          "fields": [
            {
              "name": "userName",
              "type": "text"
            }
          ]
        },
        {
          "name": "key",
          "label": "Key",
          "fields": [
            {
              "name": "apiKey",
              "type": "password"
            }
          ]
        }
      ]
    },
    {
      "name": "region",
      "type": "choice",
      "choices": [
        "eu",
        {
          "name": "us",
          "label": "United States"
        }
      ]
    },
    {
      "name": "owner",
      "type": "reference",
      "table": "sys_user",
      "query": "active=true"
    }
  ],
  "credential_fields": [
    {
      "name": "password",
      "label": "Password",
      "type": "password",
      "mandatory": true
    }
  ],
  "additional_fields": [
    {
      "name": "notes",
      "type": "text"
    }
  ]
}

sys_alias_templates.on_edit_script:
(function execute(aliasId, connectionSysId, jsonDefaultData, jsonDynamicData) {
    gs.info('on edit <' + aliasId + '> & "' + connectionSysId + '"');
})(aliasId, connectionSysId, jsonDefaultData, jsonDynamicData);
